(4766824, 687050, 67152, '<td valign="top">a very political comment on the face of food science - the image itself is pretty well delivered but the dark area of the hand of the right seems to overwhelm the shot IMO</td>', 'a very political comment on the face of food science - the image itself is pretty well delivered but the dark area of the hand of the right seems to overwhelm the shot IMO', '2008-06-12 22:18:15.000000', NULL, 1),
(4766826, 687213, 67152, '<td valign="top">a cute photo of kids and their interest in science - and thanks for putting on the safety glasses!</td>', 'a cute photo of kids and their interest in science - and thanks for putting on the safety glasses!', '2008-06-12 22:18:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4766937, 686642, 67152, '<td valign="top">nice use of repeating shapes and colors to meet the challenge - i am generally not a big fan of colored water for chemistry and science type shots - but it fits here and is well delivered</td>', 'nice use of repeating shapes and colors to meet the challenge - i am generally not a big fan of colored water for chemistry and science type shots - but it fits here and is well delivered', '2008-06-12 23:06:22.000000', NULL, 1),
(4766938, 687566, 67152, '<td valign="top">i think you have done well to make us ''feel'' the sunlight and the reaction going on</td>', 'i think you have done well to make us ''feel'' the sunlight and the reaction going on', '2008-06-12 23:06:26.000000', NULL, 1),
(4766939, 687855, 67152, '<td valign="top">the placement of the periodic table in the background is a good idea - i liek the bubbles in the test tube but i am not a big fan of the use of colored water type science shots<br/> <br/>it seems to me that the lighting on the hand could be a bit better</td>', 'the placement of the periodic table in the background is a good idea - i liek the bubbles in the test tube but i am not a big fan of the use of colored water type science shots it seems to me that the lighting on the hand could be a bit better', '2008-06-12 23:06:29.000000', NULL, 1),
(4766940, 687004, 67152, '<td valign="top">well done to show the effects of chemistry in the environment</td>', 'well done to show the effects of chemistry in the environment', '2008-06-12 23:06:33.000000', NULL, 1),
