(4767161, 686132, 90793, '<td valign="top">This idea crossed my mind but couldn''t figure out how to represent it, great idea</td>', 'This idea crossed my mind but couldn''t figure out how to represent it, great idea', '2008-06-13 02:52:33.000000', NULL, 1),
(4767166, 687522, 85063, '<td valign="top">Nice color tones! What a great picture.</td>', 'Nice color tones! What a great picture.', '2008-06-13 03:04:59.000000', NULL, 1),
(4767207, 687855, 49109, '<td valign="top">good composition, nice DOF,  the bubbles in test tube are slightly motion blurred. overall the image is a bit dull and greyish</td>', 'good composition, nice DOF,  the bubbles in test tube are slightly motion blurred. overall the image is a bit dull and greyish', '2008-06-13 05:31:14.000000', NULL, 1),
(4767208, 685720, 49109, '<td valign="top">the main subject is a bit small here; with a lower angle you could have laid more focus on the chemicals while still including the face</td>', 'the main subject is a bit small here; with a lower angle you could have laid more focus on the chemicals while still including the face', '2008-06-13 05:33:04.000000', NULL, 1),
(4767209, 687522, 49109, '<td valign="top">good color and sharpness. a bit much going on here, i don''t get how crystals, smoke and liquid  belong together</td>', 'good color and sharpness. a bit much going on here, i don''t get how crystals, smoke and liquid  belong together', '2008-06-13 05:34:42.000000', NULL, 1),
(4767210, 687757, 49109, '<td valign="top">Sugar, I think I remember... The grain adds much to the image, along with the title you could think it''s a shot from the early 20th century</td>', 'Sugar, I think I remember... The grain adds much to the image, along with the title you could think it''s a shot from the early 20th century', '2008-06-13 05:36:43.000000', NULL, 1),
(4767213, 687050, 49109, '<td valign="top">good concept. lighting could be improved and the wide angle lens definitely was the wrong choice for this</td>', 'good concept. lighting could be improved and the wide angle lens definitely was the wrong choice for this', '2008-06-13 05:38:00.000000', NULL, 1),
(4767214, 687274, 49109, '<td valign="top">good poisonous color. good crop. wish everything was a little cleaner</td>', 'good poisonous color. good crop. wish everything was a little cleaner', '2008-06-13 05:38:53.000000', NULL, 1),
(4767215, 686642, 49109, '<td valign="top">not the most original idea, but quite well executed. lighting of background could be improved</td>', 'not the most original idea, but quite well executed. lighting of background could be improved', '2008-06-13 05:39:55.000000', NULL, 1),
(4767216, 686377, 49109, '<td valign="top">very good focus and exposure but composition is quite boring</td>', 'very good focus and exposure but composition is quite boring', '2008-06-13 05:39:58.000000', NULL, 1),
