(4767218, 686132, 49109, '<td valign="top">good, different  approach to the challenge. I like the OOF foreground, nevertheless the DOF is a tad too shallow, at least the whole tongue shoulda been in focus IMO</td>', 'good, different  approach to the challenge. I like the OOF foreground, nevertheless the DOF is a tad too shallow, at least the whole tongue shoulda been in focus IMO', '2008-06-13 05:43:28.000000', NULL, 1),
(4767219, 687092, 49109, '<td valign="top">lacks a bit of focus, overall not too attractive</td>', 'lacks a bit of focus, overall not too attractive', '2008-06-13 05:44:44.000000', NULL, 1),
(4767236, 687469, 86799, '<td valign="top">Intriguing.  I don''t really get the title..."escaping" from what the picture seems to be about?  I hope you explain a little in your notes.  I really like the little bubble, it adds a little twist.  Great color and smoothness.</td>', 'Intriguing.  I don''t really get the title..."escaping" from what the picture seems to be about?  I hope you explain a little in your notes.  I really like the little bubble, it adds a little twist.  Great color and smoothness.', '2008-06-13 07:30:12.000000', NULL, 1),
(4767239, 687757, 86799, '<td valign="top">Sweet.  Oh...and nice shot, too.  A little mystery, good comp, nice tonal range.  Next time just use a spoon.  HA!</td>', 'Sweet.  Oh...and nice shot, too.  A little mystery, good comp, nice tonal range.  Next time just use a spoon.  HA!', '2008-06-13 07:39:47.000000', NULL, 1),
(4767241, 687274, 86799, '<td valign="top">Great word.  HAD to go look it up.  Nice shot, too, the color contrast is great, the wisp is so threatening, the label shouts death and danger.  Very nice.</td>', 'Great word.  HAD to go look it up.  Nice shot, too, the color contrast is great, the wisp is so threatening, the label shouts death and danger.  Very nice.', '2008-06-13 07:44:00.000000', NULL, 1),
(4767255, 687522, 71608, '<td valign="top">Lovely!</td>', 'Lovely!', '2008-06-13 08:39:36.000000', NULL, 1),
(4767256, 687750, 71608, '<td valign="top">Beautiful colours! I would love to see this shot from a couple of different angles, rather than straight on :)</td>', 'Beautiful colours! I would love to see this shot from a couple of different angles, rather than straight on :)', '2008-06-13 08:40:10.000000', NULL, 1),
(4767257, 686642, 71608, '<td valign="top">Without fault! Well done.</td>', 'Without fault! Well done.', '2008-06-13 08:40:31.000000', NULL, 1),
