(4767309, 687274, 9114, '<td valign="top">Nice one! Love that old looking bottle!<br/>Debbi</td>', 'Nice one! Love that old looking bottle!Debbi', '2008-06-13 09:28:03.000000', NULL, 1),
(4767374, 687853, 55995, '<td valign="top">Of course, they should be wearing safety goggles!!</td>', 'Of course, they should be wearing safety goggles!!', '2008-06-13 10:33:18.000000', NULL, 1),
